import{_ as e,o as a,c as r,a3 as n}from"./chunks/framework.B5WAEDB7.js";const c=JSON.parse('{"title":"Multilingual forms","description":"Maintain form text in multiple languages.","frontmatter":{"title":"Multilingual forms","description":"Maintain form text in multiple languages."},"headers":[],"relativePath":"en/formulare/mehrsprachig.md","filePath":"en/formulare/mehrsprachig.md","lastUpdated":1788108473000}'),o={name:"en/formulare/mehrsprachig.md"};function l(i,t,s,d,g,u){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="multilingual-forms" tabindex="-1">Multilingual forms <a class="header-anchor" href="#multilingual-forms" aria-label="Permalink to &quot;Multilingual forms&quot;">​</a></h1><p>A form can maintain its text in several languages. People filling it out see it in their own language.</p><p>The description in the interface: <em>Enable this feature to support multiple languages for your form.</em></p><div class="tip custom-block"><p class="custom-block-title">Included in the top plan</p><p>Multilingual support is part of the top plan. → <a href="/en/spaces/einstellungen#plan">Change plan</a></p></div><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p>In the <strong>More</strong> tab: <strong>Multiple languages</strong>. After that, <strong>Edit translations</strong> takes you to the <strong>Form language editor</strong>.</p><h2 id="default-language" tabindex="-1">Default language <a class="header-anchor" href="#default-language" aria-label="Permalink to &quot;Default language&quot;">​</a></h2><p>The <strong>Default language</strong> is the language of the text you entered in the form builder.</p><blockquote><p><em>This is the language that matches the text already set up in the form builder.</em></p></blockquote><div class="warning custom-block"><p class="custom-block-title">Don&#39;t edit the default language in the language editor</p><p>Change the default language text in the regular form editor, not in the language editor. So build the form completely in one language first, then translate it.</p></div><h2 id="adding-more-languages" tabindex="-1">Adding more languages <a class="header-anchor" href="#adding-more-languages" aria-label="Permalink to &quot;Adding more languages&quot;">​</a></h2><p>Under <strong>Additional languages</strong>, you can add as many languages as you like:</p><blockquote><p><em>Here you can add one or more additional languages.</em></p></blockquote><p>The list covers more than 180 languages, each shown in its own native name.</p><p>Use <strong>Current language</strong> to switch between the languages you&#39;re currently editing.</p><h2 id="what-gets-translated" tabindex="-1">What gets translated <a class="header-anchor" href="#what-gets-translated" aria-label="Permalink to &quot;What gets translated&quot;">​</a></h2><h3 id="global-form-text" tabindex="-1">Global form text <a class="header-anchor" href="#global-form-text" aria-label="Permalink to &quot;Global form text&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Corresponds to</th></tr></thead><tbody><tr><td><strong>Form title</strong></td><td>Form title</td></tr><tr><td><strong>Form description</strong></td><td>Description</td></tr><tr><td><strong>Submit button</strong></td><td>Label of the submit button</td></tr><tr><td><strong>Success page heading</strong></td><td>Title of the <a href="/en/formulare/erfolgsseite">success page</a></td></tr><tr><td><strong>Success page message</strong></td><td>Success page message</td></tr><tr><td><strong>Success page button</strong></td><td>Button text on the success page</td></tr></tbody></table><h3 id="form-fields" tabindex="-1">Form fields <a class="header-anchor" href="#form-fields" aria-label="Permalink to &quot;Form fields&quot;">​</a></h3><p>Labels and descriptions of all fields.</p><h3 id="text-blocks" tabindex="-1">Text blocks <a class="header-anchor" href="#text-blocks" aria-label="Permalink to &quot;Text blocks&quot;">​</a></h3><p>All inserted text and heading blocks.</p><h2 id="what-doesn-t-get-translated" tabindex="-1">What doesn&#39;t get translated <a class="header-anchor" href="#what-doesn-t-get-translated" aria-label="Permalink to &quot;What doesn&#39;t get translated&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Data stays as it is</p><p>Only the <strong>form&#39;s own text</strong> is translated — not the content:</p><ul><li><strong>Select options</strong> for a single- or multiple-select field stay in whatever language they&#39;re stored in on the Grid</li><li><strong>Linked entries</strong> appear with their value from the target Grid</li><li><strong>Error messages</strong> and system text follow the application&#39;s language setting</li></ul><p>There&#39;s no built-in solution for multilingual select options within a form. With two languages, a bilingual option is sometimes the pragmatic route — e.g. <code>Rechnung / Invoice</code>.</p></div><h2 id="working-with-it-in-practice" tabindex="-1">Working with it in practice <a class="header-anchor" href="#working-with-it-in-practice" aria-label="Permalink to &quot;Working with it in practice&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Finish first, translate last</p><p>Any later change to a field label or text block has to be reapplied in <strong>every</strong> language. So finalize the form&#39;s content first and translate it at the end.</p><p>For ongoing changes, it&#39;s worth keeping a list of which text is current in which language — the language editor doesn&#39;t show what&#39;s changed since the translation was made.</p></div><div class="tip custom-block"><p class="custom-block-title">Start with a second language</p><p>Two languages are manageable. From three or four on, every form change becomes a lot of work. Check whether you really need all the languages — or whether a separate form per language would be more practical.</p></div><h2 id="alternative-multiple-forms" tabindex="-1">Alternative: multiple forms <a class="header-anchor" href="#alternative-multiple-forms" aria-label="Permalink to &quot;Alternative: multiple forms&quot;">​</a></h2><p>Instead of one multilingual form, you can create <strong>a separate form per language</strong> on the same Grid and distribute the matching link.</p><table tabindex="0"><thead><tr><th></th><th>One multilingual form</th><th>Multiple forms</th></tr></thead><tbody><tr><td>Plan</td><td>top plan</td><td>any plan</td></tr><tr><td>Maintenance effort</td><td>one form, multiple text sets</td><td>everything duplicated per language</td></tr><tr><td>Changing structure</td><td>once</td><td>in every form</td></tr><tr><td>Links</td><td>one link</td><td>one link per language</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">When multiple forms are better</p><p>If the forms should differ by language anyway — different required fields per country, for example — separate forms are the clearer solution. They&#39;re also not tied to a specific plan.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/formulare/formular-erstellen">Creating a form</a></li><li><a href="/en/formulare/erfolgsseite">Success page and redirect</a></li><li><a href="/en/formulare/formular-teilen">Sharing a form</a></li></ul>',33)])])}const p=e(o,[["render",l]]);export{c as __pageData,p as default};
